<div class="panel"><h5 class="fw-bold"><?= esc($course['kode'].' · '.$course['nama']) ?></h5><p class="muted">Input nilai peserta mata kuliah. Nilai yang diperbolehkan: A, AB, B, BC, C, D, E.</p><form method="post" action="<?= site_url('dosen/nilai/'.$course['id']) ?>"><?= csrf_field() ?><div class="table-responsive"><table class="table"><thead><tr><th>NIM</th><th>Nama Mahasiswa</th><th>Nilai</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><?= esc($s['nim']) ?></td><td><?= esc($s['nama']) ?></td><td><select class="form-select" style="max-width:120px" name="nilai[<?= $s['krs_id'] ?>]"><option value="">Pilih nilai</option><?php foreach(['A','AB','B','BC','C','D','E'] as $g): ?><option value="<?= $g ?>" <?= $s['nilai']===$g?'selected':'' ?>><?= $g ?></option><?php endforeach ?></select></td></tr><?php endforeach ?><?php if(!$students): ?><tr><td colspan="3" class="text-center muted">Belum ada peserta pada periode aktif.</td></tr><?php endif ?></tbody></table></div><button class="btn btn-primary">Simpan Semua Nilai</button><a class="btn btn-light" href="<?= site_url('dosen/nilai') ?>">Kembali</a></form></div>